# 🟡 中风险：会修改集群/资源状态，执行前请确认目标、影响范围与授权
kubectl patch sts prometheus -n monitoring --type='merge' -p '
{
  "spec": {
    "template": {
      "spec": {
        "containers": [{
          "name": "prometheus",
          "resources": {
            "limits": {"cpu": "8", "memory": "32Gi"},
            "requests": {"cpu": "4", "memory": "16Gi"}
          }
        }]
      }
    }
  }
}'
kubectl rollout restart sts prometheus -n monitoring

